import React, { useState, useEffect } from 'react';
import { QRCodeSVG } from 'qrcode.react';
import { getCurrentUser } from '../../database/db';
import './MiQR.css';

function MiQR() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = () => {
    try {
      const currentUser = getCurrentUser();
      setUser(currentUser);
    } catch (error) {
      console.error('Error cargando usuario:', error);
    }
    setLoading(false);
  };

  const downloadQR = () => {
    const svg = document.getElementById('qr-code');
    if (!svg) return;
    
    const svgData = new XMLSerializer().serializeToString(svg);
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const img = new Image();
    
    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;
      ctx.drawImage(img, 0, 0);
      const pngFile = canvas.toDataURL('image/png');
      const downloadLink = document.createElement('a');
      const nombreUsuario = user?.Nombre || user?.nombre || 'usuario';
      downloadLink.download = `QR_${nombreUsuario}.png`;
      downloadLink.href = pngFile;
      downloadLink.click();
    };
    
    img.src = 'data:image/svg+xml;base64,' + btoa(svgData);
  };

  // Obtener valores con soporte para minúsculas (localStorage) y mayúsculas (SQL)
  const getQRValue = () => {
    return user?.QRCode || user?.qr_code || user?.Id?.toString() || user?.id?.toString() || '';
  };

  const getNombre = () => {
    return user?.Nombre || user?.nombre || 'Jugador';
  };

  const getNumeroCamiseta = () => {
    return user?.NumeroCamiseta || user?.numero_camiseta || '?';
  };

  const getPosicion = () => {
    return user?.Posicion || user?.posicion || 'Sin posición';
  };

  const getQRId = () => {
    return user?.QRCode || user?.qr_code || user?.Id || user?.id || '';
  };

  if (loading) {
    return (
      <div className="mi-qr">
        <div className="loading-container">Cargando código QR...</div>
      </div>
    );
  }

  return (
    <div className="mi-qr">
      <h2><i className="fas fa-qrcode"></i> Mi Código QR</h2>

      <div className="qr-container">
        <div className="qr-card">
          <div className="qr-header">
            <i className="fas fa-futbol"></i>
            <h3>FútbolPro</h3>
            <p>Código de Asistencia</p>
          </div>
          
          <div className="qr-code-wrapper">
            {user && (
              <QRCodeSVG
                id="qr-code"
                value={getQRValue()}
                size={200}
                bgColor="#ffffff"
                fgColor="#1e3c72"
                level="H"
                includeMargin={true}
              />
            )}
          </div>
          
          <div className="qr-info">
            <p><strong>{getNombre()}</strong></p>
            <p>#{getNumeroCamiseta()} - {getPosicion()}</p>
            <p className="qr-id">ID: {getQRId()}</p>
          </div>
          
          <button className="btn-download-qr" onClick={downloadQR}>
            <i className="fas fa-download"></i> Descargar QR
          </button>
        </div>

        <div className="qr-instructions">
          <h4><i className="fas fa-info-circle"></i> ¿Cómo usar tu código QR?</h4>
          <ol>
            <li>Guarda este código QR en tu teléfono o imprímelo</li>
            <li>Preséntalo al entrenador antes de cada entrenamiento o partido</li>
            <li>El entrenador lo escaneará para registrar tu asistencia</li>
            <li>Tu asistencia quedará verificada automáticamente</li>
          </ol>
          <div className="tips">
            <i className="fas fa-lightbulb"></i>
            <span>Tip: Puedes tomar una captura de pantalla para tenerlo siempre a mano</span>
          </div>
          <div className="tips info">
            <i className="fas fa-info-circle"></i>
            <span>Este QR es único e intransferible. No lo compartas con otras personas.</span>
          </div>
        </div>
      </div>
    </div>
  );
}

export default MiQR;
